<script setup lang="ts">import {ref} from 'vue';import {useRouter} from 'vue-router';const router=useRouter();const email=ref(''),password=ref(''),error=ref('');async function submit(){const r=await fetch('/api/v1/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:email.value,password:password.value})});if(r.ok)router.push('/');else error.value='E-mail ou senha inválidos.'}</script>
<template><div class="center"><p class="kicker">STACKHOST</p><h1>Welcome back.</h1><p class="muted">Sign in to your environment.</p><form @submit.prevent="submit"><label>Email<input v-model="email" type="email" required /></label><label>Password<input v-model="password" type="password" required /></label><p class="error">{{error}}</p><button class="primary">Sign in</button></form></div></template>
